-- Controlled scheduling between order confirmation and machine assignment.
create or replace function public.plan_factory_production(p_order uuid,p_group uuid,p_start date,p_end date,p_priority text,p_notes text default null)returns uuid language plpgsql security definer set search_path=public as $$declare v_old jsonb;v_status text;begin if not has_factory_role(auth.uid(),array['admin','production_manager'])then raise exception'not authorized';end if;if p_start is null or p_end is null or p_end<p_start then raise exception'invalid planning dates';end if;if p_priority not in('LOW','NORMAL','HIGH','URGENT')then raise exception'invalid priority';end if;select status,jsonb_build_object('status',status,'machine_group_id',machine_group_id,'planned_start_date',planned_start_date,'planned_end_date',planned_end_date,'priority',priority)into v_status,v_old from production_orders where production_order_id=p_order for update;if v_status is null then raise exception'production order not found';end if;if v_status not in('ORDER_CONFIRMED','PRODUCTION_PLANNED','MATERIALS_PENDING','MATERIALS_READY')then raise exception'order cannot be planned in its current status';end if;update production_orders set machine_group_id=p_group,planned_start_date=p_start,planned_end_date=p_end,priority=p_priority,notes=coalesce(p_notes,notes),status='PRODUCTION_PLANNED',updated_at=now(),updated_by=auth.uid()::text where production_order_id=p_order;insert into audit_log(user_id,action,entity_type,entity_id,old_value,new_value)values(auth.uid(),'Production Planned','production_orders',p_order,v_old,jsonb_build_object('status','PRODUCTION_PLANNED','machine_group_id',p_group,'planned_start_date',p_start,'planned_end_date',p_end,'priority',p_priority));return p_order;end$$;
grant execute on function public.plan_factory_production(uuid,uuid,date,date,text,text)to authenticated;
